@startuml
interface Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class BasicContract implements Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

abstract class ContractDecorator implements Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class DataOption extends ContractDecorator {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class SmsOption extends ContractDecorator {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class MinutesOption extends ContractDecorator {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class DoubleTransferRateOption extends ContractDecorator {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

Contract "1" -- "0..*" ContractDecorator : decorates
ContractDecorator "1" -- "1" Contract : wraps
@enduml

